// The universe of src/oracle.ts: every own prop the checker finds on an exported component, with what the checker says
// of it and what each tool reports (Caliper, react-docgen-typescript and react-docgen). The checker and the corpus
// root come in as arguments, so this file reads only the dumps the tools wrote. Scoring is src/tool-score.ts.
import { readFileSync, realpathSync } from 'node:fs'
import { relative } from 'node:path'
import { caliperNorm, VERDICTS, type Norm, type Verdict } from './oracle-compare.ts'
import { rdgNorm, rdtNorm } from './tool-norm.ts'
import { scoreTool, type Reported, type Stratum, type ToolScore, type UniverseProp } from './tool-score.ts'

export const normComponent = (name: string) =>
  (
    name
      .replace(/ \(.*\)$/, '')
      .split('/')
      .at(-1) ?? ''
  )
    .split('.')
    .at(-1)!
    .replaceAll(/[^A-Za-z0-9]/g, '')

export const pathKey = (path: string) =>
  process.platform === 'darwin' || process.platform === 'win32' ? path.toLowerCase() : path

/** The files of a component's collapsed inheritance layers: Caliper lists their props as members, not as props. */
export const collapsedLayerFiles = (component: any): Set<string> =>
  new Set(
    (component?.inheritance ?? [])
      .filter((layer: any) => layer.totalProps > 30)
      .map((layer: any) => pathKey(String(layer.fileName))),
  )

/** A component as the tools are matched to the checker's: the file and the normalised name. */
const componentKey = (file: string, name: string) => `${file}\0${normComponent(name)}`

export interface ToolDump {
  /** Props by component; a file with two components of one normalised name merges them, the first prop winning. */
  props: Map<string, Record<string, any>>
  /** Files the tool threw on, as paths relative to the corpus root. */
  failed: Set<string>
}

/** A dump `scripts/rdt.mjs` or `scripts/rdg.mjs` wrote. `rel` makes a path relative to the corpus root. */
export function loadTool(path: string | undefined, rel: (path: string) => string): ToolDump | undefined {
  if (!path) return undefined
  // A path that no longer exists is kept as written.
  const relOrAsIs = (p: string) => {
    try {
      return rel(p)
    } catch {
      return p
    }
  }
  const dump = JSON.parse(readFileSync(path, 'utf8'))
  const props = new Map<string, Record<string, any>>()
  for (const c of dump.components) {
    const key = componentKey(relOrAsIs(c.file), c.name ?? '')
    props.set(key, { ...c.props, ...props.get(key) })
  }
  return { props, failed: new Set<string>((dump.failedFiles ?? []).map((f: string) => relOrAsIs(f))) }
}

/** What a tool reports for one prop of one component: its type as a `Norm`, or why it has none. */
function reported(tool: ToolDump, at: { key: string; prop: string }, norm: (p: any) => Norm): Reported {
  if (tool.failed.has(at.key.split('\0')[0])) return 'failed_file'
  const props = tool.props.get(at.key)
  if (!props) return 'component'
  return at.prop in props ? norm(props[at.prop]) : 'prop'
}

type Entry = UniverseProp & { caliper: Reported; rdt?: Reported; rdg?: Reported }
interface Match {
  name: string
  key: string
  component: any
}

/** Where the checker declares a prop, by its first declaration: the component's own file, another file of the corpus, or
 * a dependency. */
function stratumOf(p: any, file: string): Stratum {
  const path = p.declarations?.[0]?.path
  if (!path) return 'unknown'
  if (String(path).includes('/node_modules/')) return 'dependency'
  return pathKey(String(path)) === pathKey(realpathSync(file)) ? 'same_file' : 'other_project_file'
}

/** What Caliper reports for one prop: the type, or why it has none. An ambiguous name is not scored for Caliper, as in
 * the verdicts of src/oracle.ts. */
function caliperReported(match: Match | undefined, p: any, caliper: any): Reported {
  const id = match?.component.props[p.name]
  if (id !== undefined) return caliperNorm(caliper.props[id].type)
  if (!match) return 'component'
  const layerFiles = collapsedLayerFiles(match.component)
  return p.declarations?.some((d: any) => layerFiles.has(pathKey(String(d.path)))) ? 'collapsed' : 'prop'
}

interface Environment {
  root: string
  caliper: any
  /** The checker and its normaliser (src/oracle-checker.ts). */
  checker: any
  checkerNorm: (type: any) => Norm
  rdt?: ToolDump
  rdg?: ToolDump
}

/** Collects the universe as components are visited. */
export function universeRecorder(env: Environment) {
  const entries: Entry[] = []
  const rel = (path: string) => relative(env.root, realpathSync(path))
  return {
    entries,
    record({ own, name, file, matches }: { own: any[]; name: string; file: string; matches: Match[] }) {
      if (own.length === 0) return
      const key = componentKey(rel(file), name)
      const types = env.checker.getTypeOfSymbol(own)
      const [match] = matches.length === 1 ? matches : []
      for (const [i, p] of own.entries()) {
        entries.push({
          component: key,
          prop: p.name,
          stratum: stratumOf(p, file),
          checker: env.checkerNorm(types[i]),
          caliper: caliperReported(match, p, env.caliper),
          rdt: env.rdt && reported(env.rdt, { key, prop: p.name }, (t) => rdtNorm(t.typeObject)),
          rdg: env.rdg && reported(env.rdg, { key, prop: p.name }, (t) => rdgNorm(t.tsType)),
        })
      }
    },
    /** One score per tool. Caliper is scored over the universe as well as over the props both list (`counts`, the
     * verdicts of src/oracle.ts): the two must agree, or the universe is not the one the verdicts were made over. */
    score(counts: Record<Verdict, number>): Record<string, ToolScore & { failed_files?: number }> {
      const caliper = scoreTool(entries, (u) => u.caliper)
      for (const verdict of VERDICTS) {
        if (caliper.verdicts[verdict] !== counts[verdict]) {
          console.error(
            `warning: Caliper "${verdict}" is ${counts[verdict]} over the shared props, not ${caliper.verdicts[verdict]} over the universe`,
          )
        }
      }
      return {
        caliper,
        ...(env.rdt && { rdt: scoreTool(entries, (u) => u.rdt!) }),
        ...(env.rdg && {
          react_docgen: { ...scoreTool(entries, (u) => u.rdg!), failed_files: env.rdg.failed.size },
        }),
      }
    },
  }
}
// Scores one tool (Caliper, react-docgen-typescript or react-docgen) against the checker over the same universe of props,
// so the three are held to the same rules. Pure: nothing here talks to the checker or reads a file.
//
// The universe is every own prop the checker finds on a component export (React's inherited DOM attributes, `ref` and
// `key` are not part of it; src/oracle.ts filters them). A tool's prop is `listed` when the tool reports it, and gets
// the same verdict the oracle gives Caliper (src/oracle-compare.ts); otherwise it is `missing`, for one of three
// reasons, and counted by where the checker says the prop is declared.
import { compare, VERDICTS, type Norm, type Verdict } from './oracle-compare.ts'

/** Where a prop the tool does not list is declared, by the checker's first declaration. */
export const STRATA = ['same_file', 'other_project_file', 'dependency', 'unknown'] as const
export type Stratum = (typeof STRATA)[number]

/** Why a tool does not list a prop: it reports no such component, the tool threw on the component's file, it reports
 * the component but not that prop, or it lists the prop only as a member of an inherited layer it collapsed
 * (Caliper's `inheritance`, which is a deliberate choice, not an omission). */
export const REASONS = ['component', 'failed_file', 'prop', 'collapsed'] as const
export type Reason = (typeof REASONS)[number]

/** One prop the checker finds, with the checker's type already reduced to a `Norm`. */
export interface UniverseProp {
  /** The component, as the tools are matched to it: file and normalised name. */
  component: string
  prop: string
  stratum: Stratum
  checker: Norm
}

/** What a tool reports for a universe prop: its type as a `Norm`, or why it has none. */
export type Reported = Norm | Reason

export interface ToolScore {
  /** Props the checker finds on the components of the universe. */
  universe: number
  listed: number
  missing: number
  verdicts: Record<Verdict, number>
  /** Identical or spelled, of the whole universe: a prop the tool omits counts against it. */
  agree_universe: number
  /** Identical or spelled, of the props the tool lists. */
  agree_listed: number
  /** Wrong, of the props the tool lists. */
  wrong_listed: number
  missing_by_stratum: Record<Stratum, number>
  missing_by_reason: Record<Reason, number>
  /** Components with at least one prop in the universe, and how many of them the tool reports at all. */
  components: number
  components_found: number
  /** The first few props of each kind the tool gets wrong or less precise, to review the adapters by. */
  examples: Record<'wrong' | 'less precise', { component: string; prop: string; tool: Norm; checker: Norm }[]>
}

const EXAMPLES = 8

const isReason = (value: Reported): value is Reason => typeof value === 'string'
const rate = (n: number, of: number) => (of === 0 ? 0 : n / of)

/** `pick` says what the tool reports for one universe prop. */
export function scoreTool<T extends UniverseProp>(universe: readonly T[], pick: (u: T) => Reported): ToolScore {
  const verdicts = Object.fromEntries(VERDICTS.map((v) => [v, 0])) as Record<Verdict, number>
  const byStratum = Object.fromEntries(STRATA.map((s) => [s, 0])) as Record<Stratum, number>
  const byReason = Object.fromEntries(REASONS.map((r) => [r, 0])) as Record<Reason, number>
  const components = new Set<string>()
  const found = new Set<string>()
  const examples: ToolScore['examples'] = { wrong: [], 'less precise': [] }
  let listed = 0
  for (const u of universe) {
    components.add(u.component)
    const reported = pick(u)
    // A component is found when any of its props is not missing for want of the component itself.
    if (!isReason(reported) || (reported !== 'component' && reported !== 'failed_file')) found.add(u.component)
    if (isReason(reported)) {
      byReason[reported]++
      // A collapsed layer is a choice, not an omission, so it has no stratum.
      if (reported !== 'collapsed') byStratum[u.stratum]++
      continue
    }
    listed++
    const verdict = compare(reported, u.checker)
    verdicts[verdict]++
    if ((verdict === 'wrong' || verdict === 'less precise') && examples[verdict].length < EXAMPLES) {
      examples[verdict].push({
        component: u.component.replace('\0', ' '),
        prop: u.prop,
        tool: reported,
        checker: u.checker,
      })
    }
  }
  const agree = verdicts.identical + verdicts.spelled
  return {
    universe: universe.length,
    listed,
    missing: universe.length - listed,
    verdicts,
    agree_universe: rate(agree, universe.length),
    agree_listed: rate(agree, listed),
    wrong_listed: rate(verdicts.wrong, listed),
    missing_by_stratum: byStratum,
    missing_by_reason: byReason,
    components: components.size,
    components_found: found.size,
    examples,
  }
}
// TypeScript 7.1's checker as a test oracle for Caliper's prop types (docs/parity.md). Test-only: the opt-in semantic
// backend is a separate, experimental feature.
//
// For one corpus, finds components the way react-docgen-typescript does (an exported function whose only or `props`
// parameter is the props type), reads each prop's type from the checker, and compares it structurally with the prop
// Caliper's canonical JSON reports for the same component (src/oracle-compare.ts). Each shared prop gets one verdict:
//
//   identical          both sides describe the same type
//   spelled            the same type, Caliper by name where the checker expands it, or the reverse
//   less precise       Caliper's type is looser or unevaluated (an opaque type, `string` for a literal union, a name
//                      left unexpanded, a lost optional or rest parameter, a missing field)
//   wrong              Caliper's type describes something else
//   checker any/error  the checker itself has no type (an unresolved import, `any`, or `unknown` where Caliper has one)
//
// Checker types are normalized once per type id and verdicts made once per (Caliper prop, checker type), so Chakra's
// ~470,000 props cost a few thousand distinct comparisons.
//
// With `--rdt` and `--rdg` (the dumps scripts/rdt.mjs and scripts/rdg.mjs write) the report also scores react-docgen-
// typescript and react-docgen over every own prop the checker finds (`tools`; src/tool-universe.ts).
import { readdirSync, readFileSync, realpathSync, writeFileSync } from 'node:fs'
import { join, relative } from 'node:path'
import { API, SignatureKind, SymbolFlags } from 'typescript-beta/sync'
import { checkerNormalizer } from './oracle-checker.ts'
import { caliperNorm, compare, VERDICTS, type Norm, type Verdict } from './oracle-compare.ts'
import { collapsedLayerFiles, loadTool, normComponent, pathKey, universeRecorder } from './tool-universe.ts'

const KEYS = ['root', 'src', 'tsconfig', 'caliper', 'out', 'files', 'dump', 'rows', 'missing', 'rdt', 'rdg'] as const
const args: Partial<Record<(typeof KEYS)[number], string>> = {}
for (let i = 2; i < process.argv.length; i += 2) {
  args[process.argv[i].replace(/^--/, '') as (typeof KEYS)[number]] = process.argv[i + 1]
}
if (!args.root || !args.src || !args.tsconfig || !args.caliper || !args.out) {
  console.error(
    'usage: tsx src/oracle.ts --root DIR --src DIR --tsconfig FILE --caliper FILE --out FILE [--rdt F] [--rdg F]',
  )
  process.exit(2)
}
const root = realpathSync(args.root)

function walk(dir: string): string[] {
  const out: string[] = []
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (entry.name === 'node_modules') continue
    const path = join(dir, entry.name)
    if (entry.isDirectory()) out.push(...walk(path))
    else out.push(path)
  }
  return out
}

const files: string[] = args.files
  ? readFileSync(args.files, 'utf8').split('\n').filter(Boolean)
  : walk(realpathSync(args.src))
      .filter((f) => f.endsWith('.tsx'))
      .toSorted()

const api = new API({ cwd: root })
const programStart = performance.now()
// The same program react-docgen-typescript parses in scripts/weekly.py: the component files, with the tsconfig it
// uses. The options go through `parseConfigFile` because the 7.1 beta's server panics on string-valued enum options
// passed to `createProgram` directly.
const { options } = api.parseConfigFile(args.tsconfig)
const program = api.createProgram(files, options)
const { checker } = program.getProject()
const programMs = performance.now() - programStart
const checkerNorm = checkerNormalizer(checker)

// ─── Components ───────────────────────────────────────────────────────────────

const rel = (path: string) => relative(root, realpathSync(path))

const caliper = JSON.parse(readFileSync(args.caliper, 'utf8'))
const caliperByFile = new Map<string, { name: string; key: string; component: any }[]>()
for (const [componentKey, component] of Object.entries<any>(caliper.components)) {
  // Schema 2 lists a component's prop set ids, each a map of prop name to prop id; this reads one map of both.
  if (Array.isArray(component.props)) {
    component.props = Object.assign({}, ...component.props.map((id: string) => caliper.propSets[id]))
  }
  const key = rel(component.filePath)
  const list = caliperByFile.get(key) ?? []

